// ============================================================

const RUNTIME_PREAMBLE = `
// ── FreeLang v8 ML Runtime Helpers ──────────────────────────
function range(start, end, step) {
  if (end === undefined) { end = start; start = 0; }
  if (step === undefined) { step = 1; }
  const result = [];
  if (step > 0) { for (let i = start; i < end; i += step) result.push(i); }
  else          { for (let i = start; i > end; i += step) result.push(i); }
  return result;
}

function __matmul__(a, b) {
  // 2D matrix multiply
  if (!Array.isArray(a) || !Array.isArray(b)) throw new Error("__matmul__: both operands must be arrays");
  const rowsA = a.length, colsA = a[0].length;
  const rowsB = b.length, colsB = b[0].length;
  if (colsA !== rowsB) throw new Error("__matmul__: incompatible shapes");
  const result = [];
  for (let i = 0; i < rowsA; i++) {
    result[i] = [];
    for (let j = 0; j < colsB; j++) {
      let sum = 0;
      for (let k = 0; k < colsA; k++) sum += a[i][k] * b[k][j];
      result[i][j] = sum;
    }
  }
  return result;
}

function __transpose__(a) {
  if (!Array.isArray(a) || !Array.isArray(a[0])) throw new Error("__transpose__: expected 2D array");
  const rows = a.length, cols = a[0].length;
  const result = [];
  for (let j = 0; j < cols; j++) {
    result[j] = [];
    for (let i = 0; i < rows; i++) result[j][i] = a[i][j];
  }
  return result;
}
// ─────────────────────────────────────────────────────────────
`;

// ============================================================
// CompileResult
// ============================================================

export interface CompileResult {
  ok: boolean;
  js?: string;
  errors?: string[];
}

// ============================================================
// FL8CodeGen
// ============================================================

export class FL8CodeGen {
  private needsMatmul = false;
  private needsTranspose = false;

  // ── 진입점 ──────────────────────────────────────────────────

  generate(program: Program): string {
    this.needsMatmul = false;
    this.needsTranspose = false;

    const body = program.stmts.map(s => this.genStmt(s, 0)).join("\n");

    let preamble = RUNTIME_PREAMBLE;
    return preamble + "\n" + body;
  }

  // ── 문(Statement) ───────────────────────────────────────────

  genStmt(stmt: Stmt, indent: number): string {
    const pad = "  ".repeat(indent);
    switch (stmt.kind) {

      // let x = expr
      case "var_decl": {
        const kw = stmt.mutable ? "let" : "let";
        const val = this.genExpr(stmt.init);
        return `${pad}${kw} ${stmt.name} = ${val};`;
      }

      // fn f(params) { body }
      case "fn_decl": {
        const params = stmt.params.map(p => p.name).join(", ");
        const bodyLines = stmt.body.map(s => this.genStmt(s, indent + 1)).join("\n");
        return `${pad}function ${stmt.name}(${params}) {\n${bodyLines}\n${pad}}`;
      }

      // struct → JS class (기본 변환)
      case "struct_decl": {
        const fields = stmt.fields.map(f => `this.${f.name} = ${f.name};`).join(" ");
        const paramList = stmt.fields.map(f => f.name).join(", ");
        return `${pad}class ${stmt.name} {\n${pad}  constructor(${paramList}) { ${fields} }\n${pad}}`;
      }

      // if / else
      case "if_stmt": {
        const cond = this.genExpr(stmt.condition);
        const thenLines = stmt.then.map(s => this.genStmt(s, indent + 1)).join("\n");
        let result = `${pad}if (${cond}) {\n${thenLines}\n${pad}}`;
        if (stmt.else_ && stmt.else_.length > 0) {
          const elseLines = stmt.else_.map(s => this.genStmt(s, indent + 1)).join("\n");
          result += ` else {\n${elseLines}\n${pad}}`;
        }
        return result;
      }

      // while cond { body }
      case "while_stmt": {
        const cond = this.genExpr(stmt.condition);
        const bodyLines = stmt.body.map(s => this.genStmt(s, indent + 1)).join("\n");
        return `${pad}while (${cond}) {\n${bodyLines}\n${pad}}`;
      }

      // for x in iterable { body }  →  for (const x of <iterable>) { ... }
      case "for_stmt": {
        const iter = this.genExpr(stmt.iterable);
        const bodyLines = stmt.body.map(s => this.genStmt(s, indent + 1)).join("\n");
        return `${pad}for (const ${stmt.variable} of ${iter}) {\n${bodyLines}\n${pad}}`;
      }

      // for_of_stmt (별도 노드)
      case "for_of_stmt": {
        const iter = this.genExpr(stmt.iterable);
        const bodyLines = stmt.body.map(s => this.genStmt(s, indent + 1)).join("\n");
        return `${pad}for (const ${stmt.variable} of ${iter}) {\n${bodyLines}\n${pad}}`;
      }

      case "break_stmt":
        return `${pad}break;`;

      case "continue_stmt":
        return `${pad}continue;`;

      case "return_stmt": {
        if (stmt.value === null) return `${pad}return;`;
        return `${pad}return ${this.genExpr(stmt.value)};`;
      }

      case "expr_stmt": {
        return `${pad}${this.genExpr(stmt.expr)};`;
      }

      // spawn → 단순 함수 호출로 변환 (async 미지원)
      case "spawn_stmt": {
        const bodyLines = stmt.body.map(s => this.genStmt(s, indent + 1)).join("\n");
        return `${pad}(function() {\n${bodyLines}\n${pad}})();`;
      }

      // match → switch 변환 (기본)
      case "match_stmt": {
        const subj = this.genExpr(stmt.subject);
        const cases = stmt.arms.map(arm => {
          const bodyExpr = this.genExpr(arm.body);
          if (arm.pattern.kind === "wildcard") {
            return `${pad}  default: ${bodyExpr}; break;`;
          } else if (arm.pattern.kind === "literal") {
            const lit = this.genExpr(arm.pattern.value);
            return `${pad}  case ${lit}: ${bodyExpr}; break;`;
          } else if (arm.pattern.kind === "ident") {
            return `${pad}  default: { let ${arm.pattern.name} = ${subj}; ${bodyExpr}; break; }`;
          }
          return `${pad}  default: ${bodyExpr}; break;`;
        }).join("\n");
        return `${pad}switch (${subj}) {\n${cases}\n${pad}}`;
      }

      default:
        return `${pad}/* unsupported stmt: ${(stmt as any).kind} */`;
    }
  }

  // ── 식(Expression) ──────────────────────────────────────────

  genExpr(expr: Expr): string {
    switch (expr.kind) {

      case "int_lit":
        return String(expr.value);

      case "float_lit":
        return String(expr.value);

      case "string_lit":
        // 이스케이프 처리: 백슬래시를 포함한 문자열 그대로 출력
        return JSON.stringify(expr.value);

      case "bool_lit":
        return expr.value ? "true" : "false";

      case "ident":
        return expr.name;

      // 산술/비교/논리 연산자
      case "binary": {
        const l = this.genExpr(expr.left);
        const r = this.genExpr(expr.right);
        // FL8 연산자 → JS 연산자 직접 매핑
        const op = this.mapOperator(expr.op);
        return `(${l} ${op} ${r})`;
      }

      case "unary": {
        const operand = this.genExpr(expr.operand);
        return `(${expr.op}${operand})`;
      }

      // 함수 호출: print(...) → console.log(...)
      case "call": {
        const args = expr.args.map(a => this.genExpr(a)).join(", ");
        if (expr.callee.kind === "ident" && expr.callee.name === "print") {
          return `console.log(${args})`;
        }
        if (expr.callee.kind === "ident" && expr.callee.name === "println") {
          return `console.log(${args})`;
        }
        const callee = this.genExpr(expr.callee);
        return `${callee}(${args})`;
      }

      // 인덱스 접근 a[i]
      case "index": {
        const obj = this.genExpr(expr.object);
        const idx = this.genExpr(expr.index);
        return `${obj}[${idx}]`;
      }

      // 필드 접근 a.field
      case "field_access": {
        const obj = this.genExpr(expr.object);
        return `${obj}.${expr.field}`;
      }

      // 할당 target = value
      case "assign": {
        const target = this.genExpr(expr.target);
        const value = this.genExpr(expr.value);
        return `${target} = ${value}`;
      }

      // 배열 리터럴 [1, 2, 3]
      case "array_lit": {
        const elems = expr.elements.map(e => this.genExpr(e)).join(", ");
        return `[${elems}]`;
      }

      // 구조체 리터럴 → 객체 리터럴
      case "struct_lit": {
        const fields = expr.fields.map(f => `${f.name}: ${this.genExpr(f.value)}`).join(", ");
        return `{ ${fields} }`;
      }

      // 람다/익명 함수
      case "fn_lit": {
        const params = expr.params.map(p => p.name).join(", ");
        const body = this.genExpr(expr.body);
        return `function(${params}) { return ${body}; }`;
      }

      // 블록 식 { stmts; expr }
      case "block_expr": {
        // IIFE로 변환
        const stmts = expr.stmts.map(s => this.genStmt(s, 1)).join("\n");
        const retExpr = expr.expr ? `\n  return ${this.genExpr(expr.expr)};` : "";
        return `(function() {\n${stmts}${retExpr}\n})()`;
      }

      // if 식
      case "if_expr": {
        const cond = this.genExpr(expr.condition);
        // 단순 삼항 또는 IIFE
        const thenStmts = expr.then.map(s => this.genStmt(s, 1)).join("\n");
        const elseStmts = expr.else_.map(s => this.genStmt(s, 1)).join("\n");
        return `(function() { if (${cond}) {\n${thenStmts}\n} else {\n${elseStmts}\n} })()`;
      }

      // match 식
      case "match_expr": {
        const subj = this.genExpr(expr.subject);
        const arms = expr.arms.map(arm => {
          const bodyExpr = this.genExpr(arm.body);
          if (arm.pattern.kind === "wildcard") {
            return `true ? (${bodyExpr}) : undefined`;
          } else if (arm.pattern.kind === "literal") {
            const lit = this.genExpr(arm.pattern.value);
            return `(__m === ${lit}) ? (${bodyExpr}) : undefined`;
          } else if (arm.pattern.kind === "ident") {
            return `(function(${arm.pattern.name}) { return ${bodyExpr}; })(__m)`;
          }
          return `(${bodyExpr})`;
        });
        // 체이닝 삼항
        return `(function() { let __m = ${subj}; return ${arms[0] ?? "undefined"}; })()`;
      }

      // ML v8: 행렬곱 A @ B
      case "matmul": {
        const l = this.genExpr(expr.left);
        const r = this.genExpr(expr.right);
        return `__matmul__(${l}, ${r})`;
      }

      // ML v8: 전치 A.T
      case "transpose": {
        const operand = this.genExpr(expr.operand);
        return `__transpose__(${operand})`;
      }

      // ML v8: 텐서 리터럴 (중첩 배열로 변환)
      case "tensor_lit": {
        const elems = expr.elements.map(e => this.genExpr(e)).join(", ");
        return `[${elems}]`;
      }

      // ML v8: grad 블록
      case "grad_block": {
        const stmts = expr.body.map(s => this.genStmt(s, 1)).join("\n");
        return `(function() {\n${stmts}\n})()`;
      }

      // try 연산자 (? 연산자) → 단순 값 반환
      case "try": {
        return this.genExpr(expr.operand);
      }

      default:
        return `/* unsupported expr: ${(expr as any).kind} */`;
    }
  }

  // ── 연산자 매핑 ─────────────────────────────────────────────

  private mapOperator(op: string): string {
    switch (op) {
      case "==":  return "===";
      case "!=":  return "!==";
      case "and": return "&&";
      case "or":  return "||";
      case "not": return "!";
      default:    return op;
    }
  }
}

// ============================================================
// compile() — FL8 소스 → CompileResult
// ============================================================

export function compile(source: string): CompileResult {
  // Lex
  const lexer = new Lexer(source);
  const { tokens, errors: lexErrors } = lexer.tokenize();
  if (lexErrors.length > 0) {
    return { ok: false, errors: lexErrors.map(e => `Lex:${e.line}:${e.col}: ${e.message}`) };
  }

  // Parse
  const parser = new Parser(tokens);
  const { program, errors: parseErrors } = parser.parse();
  if (parseErrors.length > 0) {
    return { ok: false, errors: parseErrors.map(e => `Parse:${e.line}:${e.col}: ${e.message}`) };
  }

  // Codegen
  try {
    const codegen = new FL8CodeGen();
    const js = codegen.generate(program);
    return { ok: true, js };
  } catch (e: any) {
    return { ok: false, errors: [`Codegen: ${e.message}`] };
  }
}

// FreeLang v8 ML — Phase 12 AOT 코드 생성 테스트
// FL8 소스 → JavaScript 트랜스파일 & 실행 검증

import * as vm from "vm";
import { compile } from "../src/compiler/codegen";

// ============================================================
// 테스트 프레임워크
// ============================================================

let passed = 0;
let failed = 0;
const failedNames: string[] = [];

function test(name: string, fn: () => void): void {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
    failedNames.push(name);
  }
}

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error(msg);
}

function assertEqual<T>(a: T, b: T, msg?: string): void {
  const ja = JSON.stringify(a);
  const jb = JSON.stringify(b);
  if (ja !== jb) throw new Error(msg ?? `expected ${jb}, got ${ja}`);
}

// ============================================================
// JS 실행기 (vm.runInContext)
// ============================================================

function runJS(js: string): { output: string[]; error?: string } {
  const output: string[] = [];
  const ctx = vm.createContext({
    console: { log: (...args: any[]) => output.push(args.map(String).join(" ")) },
    Math,
    Array,
    Object,
    JSON,
  });
  try {
    vm.runInContext(js, ctx);
    return { output };
  } catch (e: any) {
    return { output, error: e.message };
  }
}

function compileAndRun(src: string): { ok: boolean; output: string[]; error?: string; js?: string } {
  const result = compile(src);
  if (!result.ok || !result.js) {
    return { ok: false, output: [], error: (result.errors ?? []).join("; ") };
  }
  const { output, error } = runJS(result.js);
  return { ok: true, output, error, js: result.js };
}

